// Шаблоны для Канады (язык документов — английский).
// Основано на федеральном законодательстве Канады и провинциальных актах:
// Canada Labour Code (R.S.C., 1985, c. L-2) — s. 169 (hours), s. 174 (overtime),
// s. 177.1 (flexible work request), ss. 185–196 (annual vacations, min. 2 weeks /
// 4%), s. 206 et seq. (pregnancy, maternity and parental leave), s. 206.3
// (compassionate care), s. 230 (notice of termination — federally regulated);
// Employment Insurance Act, ss. 112–120 (reconsideration / appeal to the Social
// Security Tribunal, 30 дней); Canada Pension Plan, ss. 65–66 (reconsideration,
// 90 дней); Employment Insurance Regulations (ROE — 5 календарных дней);
// Income Tax Act — s. 165 (Notice of Objection, 90 дней), ss. 152(1.1), 152(4)
// (T1 adjustment), s. 220(3.1) (Taxpayer Relief); PIPEDA (S.C. 2000, c. 5) — s. 8
// (доступ к персональным данным, 30 дней), s. 11 (жалоба в OPC);
// Financial Consumer Agency of Canada Act; Bank Act (S.C. 1991, c. 46);
// Canada Post Corporation Act (претензии по почте).
// Провинции: Employment Standards Act, 2000 (Ontario) — ss. 33–35 (vacation),
// ss. 54–61 (notice of termination); Residential Tenancies Act, 2006 (Ontario) —
// s. 20 (maintenance), s. 37 (notice by tenant, 60 дней); Substitute Decisions
// Act, 1992 (Ontario), Part II (power of attorney for property); Consumer
// Protection Act, 2002 (Ontario) — future performance agreements.
// Большинство работников подпадает под ПРОВИНЦИАЛЬНЫЕ трудовые стандарты:
// где это существенно, в шаблоне есть поле «province», а ссылки даны
// обобщённо (provincial employment standards / provincial tenancy legislation).
import type { TplDef } from '../types';
import { F, hdr, stdSign } from './helpers';

const workHdr = (): TplDef['body'] => [
  { type: 'lines', align: 'right', items: ['{{date_today}}', '', 'To: {{manager_name}}', '{{org_name}}', '', 'From: {{applicant_name}}', '{{applicant_position}}'] },
];

const workFields = (extra: TplDef['fields'] = []): TplDef['fields'] => [
  F('org_name', 'Название компании', 'Company name', 'text', { half: true, placeholderDoc: 'Northern Lights Logistics Ltd.' }),
  F('manager_name', 'Кому (руководитель/HR)', 'Manager / HR (attention)', 'text', { half: true, placeholderDoc: 'Ms. D. MacLeod (HR)' }),
  F('applicant_name', 'Ваше имя', 'Your full name', 'text', { half: true, placeholderDoc: 'Emma Tremblay' }),
  F('applicant_position', 'Ваша должность', 'Your position', 'text', { half: true, placeholderDoc: 'Customer Service Representative' }),
  ...extra,
];

